/* Recreated Doom status bar: pure logic (no VDP access), host-testable. GPL-2.0-or-later.
 *
 * Requires "hud_wad_assets.h" (generated by scripts/lab/gen_hud_wad.py from the user's IWAD) to be included first.
 * HUDW_ComposeRow() turns a snapshot of the player into the 32 tilemap words of one bar row (palette line 3, high priority);
 * HUDW_Face* is a port of ST_updateFaceWidget() from the original status bar, with no state beyond a few bytes. */
#ifndef HUD_WAD_LOGIC_H
#define HUD_WAD_LOGIC_H
#include <stdint.h>

#ifndef HUDW_VRAM_BASE
#define HUDW_VRAM_BASE 800u              /* free in gameplay: pair tiles use 256..767, the SGDK font starts at 1440 */
#endif
#define HUDW_FACE_SLOT HUDW_NTILES       /* HUDW_FACE_W x 4 tiles after the static ones hold the current face */
#define HUDW_WORD(id) ((uint16_t)(0xE000u | (HUDW_VRAM_BASE + (uint16_t)(id))))   /* priority + palette 3 */
#define HUDW_FWORD(id) ((uint16_t)(0xC000u | (HUDW_VRAM_BASE + (uint16_t)(id))))  /* priority + palette 2: the face slot */

typedef struct {
    int16_t health, armor, ammo_r;       /* ammo_r < 0: weapon without ammo */
    int16_t ammo[4], maxammo[4];
    uint8_t arms;                        /* bit i: weapon number i+2 owned */
    uint8_t keys;                        /* bit 0..2: blue, yellow, red card */
    uint8_t face;                        /* 0..41, see HUDW_Face* */
} HudState;

/* One tile row of a big number: only the digits that are shown replace the background tile, so blanks show the stone behind. */
static void hudw_big_row(uint16_t *out, uint8_t c0, uint8_t row, int16_t v, uint8_t pct)
{
    if (v < 0) v = 0;
    if (v > 999) v = 999;
    uint8_t d[3] = {(uint8_t)(v / 100), (uint8_t)(v / 10 % 10), (uint8_t)(v % 10)};
    uint8_t lead[3] = {v >= 100, v >= 10, 1};
    for (uint8_t i = 0; i < 3; i++)
        if (lead[i]) out[c0 + i] = hudw_big[d[i]][row];
    if (pct) out[c0 + 3] = hudw_pct[row];
}

/* out[32]: tilemap ids of bar row `row` (0..3). */
static void hudw_compose_ids(const HudState *s, uint8_t row, uint16_t *out)
{
    for (uint8_t c = 0; c < HUDW_COLS; c++) out[c] = hudw_bgmap[row][c];
    if (row < 3) {
        if (s->ammo_r >= 0) hudw_big_row(out, HUDW_AMMO_C, row, s->ammo_r, 0);
        hudw_big_row(out, HUDW_HEALTH_C, row, s->health, 1);
        hudw_big_row(out, HUDW_ARMOR_C, row, s->armor, 1);
    }
    uint16_t mask = (uint16_t)(s->arms | (s->keys << 6));
    for (uint8_t k = 0; k < HUDW_NWID; k++)
        if (hudw_wid_row[k] == row) {
            uint8_t v = (uint8_t)((mask >> hudw_wid_b0[k]) & 1);
            if (hudw_wid_b1[k] != 255) v |= (uint8_t)(((mask >> hudw_wid_b1[k]) & 1) << 1);
            out[hudw_wid_col[k]] = hudw_wid_id[k][v];
        }
    if ((unsigned)((int)row - HUDW_FACE_R) < 4u)
        for (uint8_t c = 0; c < HUDW_FACE_W; c++)
            out[HUDW_FACE_C + c] = (uint16_t)(HUDW_FACE_SLOT + (row - HUDW_FACE_R) * HUDW_FACE_W + c);
    if ((unsigned)((int)row - HUDW_TABLE_R) < 4u) {
        uint8_t t = (uint8_t)(row - HUDW_TABLE_R);
        for (uint8_t part = 0; part < 2; part++) {
            int16_t v = part ? s->maxammo[t] : s->ammo[t];
            if (v < 0) v = 0;
            if (v > 999) v = 999;
            uint8_t d[3] = {(uint8_t)(v / 100), (uint8_t)(v / 10 % 10), (uint8_t)(v % 10)};
            uint8_t lead[3] = {v >= 100, v >= 10, 1};
            for (uint8_t i = 0; i < 3; i++)
                if (lead[i]) out[HUDW_TABLE_C + part * 3 + i] = hudw_ysm[t][d[i]];
        }
    }
}

static void HUDW_ComposeRow(const HudState *s, uint8_t row, uint16_t *out)
{
    hudw_compose_ids(s, row, out);
    for (uint8_t c = 0; c < HUDW_COLS; c++) out[c] = out[c] >= HUDW_NTILES ? HUDW_FWORD(out[c]) : HUDW_WORD(out[c]);
}

/* 16-bit digest of the displayed state: redraw only when it changes. */
static uint16_t HUDW_Hash(const HudState *s)
{
    uint16_t h = 0x5A5Au;
    const int16_t *v[] = {&s->health, &s->armor, &s->ammo_r};
    for (uint8_t i = 0; i < 3; i++) h = (uint16_t)((h << 5 | h >> 11) ^ (uint16_t)*v[i]);
    for (uint8_t i = 0; i < 4; i++) {
        h = (uint16_t)((h << 5 | h >> 11) ^ (uint16_t)s->ammo[i]);
        h = (uint16_t)((h << 5 | h >> 11) ^ (uint16_t)s->maxammo[i]);
    }
    h = (uint16_t)((h << 5 | h >> 11) ^ (uint16_t)(s->arms | s->keys << 8));
    return h;     /* the face is uploaded separately, so it is not part of the digest */
}

/* ---- face: port of ST_updateFaceWidget (priorities 9..0) -------------------------------------------------------------------- */
#define HUDW_FACESTRIDE 8
#define HUDW_STRAIGHT 0
#define HUDW_TURNOFF 3
#define HUDW_OUCH 5
#define HUDW_EVIL 6
#define HUDW_RAGE 7
#define HUDW_GODFACE 40
#define HUDW_DEADFACE 41
#define HUDW_MUCHPAIN 20

typedef struct {                          /* what the face needs from the player, per tic */
    int16_t health, damagecount, bonuscount;
    uint8_t attackdown, god, has_attacker;
    uint16_t weapons;                     /* bit w: weaponowned[w] */
    uint32_t angle_to_attacker, mo_angle; /* angle_t */
    uint16_t random;                      /* any per-tic pseudo random value */
} HudFaceIn;

/* Packed to 6 bytes (BSS is at its ceiling): the face must fit next to the 57,920 B limit of the R66 builds. */
typedef struct {
    uint16_t index : 6;                   /* 0..41, see HUDW_Face* */
    uint16_t shown : 6;                   /* face currently uploaded to VRAM, 63 = none */
    uint16_t priority : 4;                /* 0..9 */
    uint16_t count : 7;                   /* tics until the next idle face, <= 70 */
    uint16_t lastattack : 7;              /* 0 = not attacking, else tics until rage + 1 (<= 71) */
    uint8_t oldhealth;                    /* clamped to 0..255 (health never exceeds 200) */
    uint8_t oldweapons;                   /* weapon bits folded to 8 bits: change detector only */
} HudFace;

#define HUDW_FOLD(w) ((uint8_t)(((w) ^ ((w) >> 8)) & 0xFFu))
#define HUDW_CLAMPH(h) ((uint8_t)((h) < 0 ? 0 : (h) > 255 ? 255 : (h)))

static uint8_t hudw_pain_offset(int16_t health)
{
    if (health > 100) health = 100;
    if (health < 0) health = 0;
    return (uint8_t)(HUDW_FACESTRIDE * (((100 - health) * 5) / 101));
}

static void HUDW_FaceInit(HudFace *f, int16_t health, uint16_t weapons)
{
    f->index = 0; f->shown = 63; f->count = 0; f->priority = 0; f->lastattack = 0; f->oldhealth = HUDW_CLAMPH(health); f->oldweapons = HUDW_FOLD(weapons);
}

static void HUDW_FaceTick(HudFace *f, const HudFaceIn *p)
{
    if (f->priority < 10 && p->health <= 0) { f->priority = 9; f->index = HUDW_DEADFACE; f->count = 1; }
    if (f->priority < 9 && p->bonuscount) {
        if (f->oldweapons != HUDW_FOLD(p->weapons)) {
            f->oldweapons = HUDW_FOLD(p->weapons);
            f->priority = 8; f->count = 70;                         /* 2 * TICRATE */
            f->index = (uint8_t)(hudw_pain_offset(p->health) + HUDW_EVIL);
        }
    }
    if (f->priority < 8 && p->damagecount && p->has_attacker) {
        f->priority = 7;
        if ((int16_t)f->oldhealth - p->health > HUDW_MUCHPAIN) {
            f->count = 35;
            f->index = (uint8_t)(hudw_pain_offset(p->health) + HUDW_OUCH);
        } else {
            uint32_t diff; uint8_t right;
            if (p->angle_to_attacker > p->mo_angle) { diff = p->angle_to_attacker - p->mo_angle; right = diff > 0x80000000u; }
            else { diff = p->mo_angle - p->angle_to_attacker; right = diff <= 0x80000000u; }
            f->count = 35;
            f->index = hudw_pain_offset(p->health);
            if (diff < 0x20000000u) f->index += HUDW_RAGE;           /* ANG45 */
            else f->index += right ? HUDW_TURNOFF : HUDW_TURNOFF + 1;
        }
    }
    if (f->priority < 7 && p->damagecount) {
        if ((int16_t)f->oldhealth - p->health > HUDW_MUCHPAIN) {
            f->priority = 7; f->count = 35; f->index = (uint8_t)(hudw_pain_offset(p->health) + HUDW_OUCH);
        } else {
            f->priority = 6; f->count = 35; f->index = (uint8_t)(hudw_pain_offset(p->health) + HUDW_RAGE);
        }
    }
    if (f->priority < 7) f->oldhealth = HUDW_CLAMPH(p->health);                   /* the original refreshes it inside this block */
    if (f->priority < 6) {
        if (p->attackdown) {
            if (!f->lastattack) f->lastattack = 71;                      /* original: -1 -> 70 (stored +1) */
            else if (--f->lastattack == 1) {                               /* original: !--lastattack */
                f->priority = 5; f->index = (uint8_t)(hudw_pain_offset(p->health) + HUDW_RAGE); f->count = 1; f->lastattack = 2;
            }
        } else f->lastattack = 0;
    }
    if (f->priority < 5 && p->god) { f->priority = 4; f->index = HUDW_GODFACE; f->count = 1; }
    if (!f->count) {
        f->index = (uint8_t)(hudw_pain_offset(p->health) + (p->random % 3));
        f->count = 17;                                                /* TICRATE / 2 */
        f->priority = 0;
    }
    f->count--;
}
#endif
